// ======================= CONFIGURAÇÃO =======================
// Ajuste aqui origens, datas, roteiros, passageiros e preço-alvo.
const CONFIG = {
  ORIGENS: ['GRU'],                       // ex.: ['GRU', 'GIG', 'CNF']
  DATAS_IDA: ['2027-10-01', '2027-10-08', '2027-10-15'],
  DURACAO_DIAS: 10,                       // voo noturno: chega em ida+1 e volta em ida+10 (10 dias na Itália)
  // Chegada sempre em Roma; saída por Roma, Nápoles ou Bari (open-jaw)
  SAIDAS: ['FCO', 'NAP', 'BRI'],
  ADULTOS: 2,
  MOEDA: 'BRL',
  PRECO_ALVO_TOTAL: 10000,                // R$ para TODOS os adultos (ida+volta)
  QUEDA_MINIMA_PCT: 3,                    // só avisa nova mínima se cair >= 3%
  EMAIL_DESTINO: 'PREENCHA@seu-email.com',
  EMAIL_REMETENTE: 'Radar de Voos <comercial@antere.com.br>',
};
// ============================================================

if (CONFIG.EMAIL_DESTINO.startsWith('PREENCHA')) {
  throw new Error('Configure EMAIL_DESTINO no topo do nó 02_monta_buscas antes de ativar o workflow.');
}

const addDias = (iso, n) => {
  const d = new Date(iso + 'T12:00:00Z');
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0, 10);
};

const buscas = [];
for (const origem of CONFIG.ORIGENS) {
  for (const ida of CONFIG.DATAS_IDA) {
    const volta = addDias(ida, CONFIG.DURACAO_DIAS);
    for (const saida of CONFIG.SAIDAS) {
      const chave = `${origem}-FCO_${ida}__${saida}-${origem}_${volta}`;
      const base = {
        engine: 'google_flights',
        hl: 'pt-br',
        gl: 'br',
        currency: CONFIG.MOEDA,
        adults: CONFIG.ADULTOS,
        travel_class: 1,
      };
      let query;
      if (saida === 'FCO') {
        query = { ...base, type: 1, departure_id: origem, arrival_id: 'FCO', outbound_date: ida, return_date: volta };
      } else {
        query = {
          ...base,
          type: 3,
          multi_city_json: JSON.stringify([
            { departure_id: origem, arrival_id: 'FCO', date: ida },
            { departure_id: saida, arrival_id: origem, date: volta },
          ]),
        };
      }
      buscas.push({ chave, origem, ida, volta, saida, query });
    }
  }
}

// Modo sentinela: enquanto o Google Voos ainda não publicou voos para as
// datas (companhias abrem a venda ~330 dias antes), faz UMA única busca —
// a de volta mais distante — para economizar cota da SerpApi.
const estado = $getWorkflowStaticData('global');
let lista = buscas;
if (!estado.disponivel) {
  lista = [buscas.slice().sort((a, b) => b.volta.localeCompare(a.volta))[0]];
}

return lista.map(b => ({ json: { ...b, config: CONFIG, modo: estado.disponivel ? 'completo' : 'sentinela' } }));

// Analisa as respostas da SerpApi (Google Voos).
// REGRA PRINCIPAL: se não houver voos, não retorna nada -> nenhuma mensagem é enviada.
const buscas = $('02_monta_buscas').all();
const respostas = $input.all();
const estado = $getWorkflowStaticData('global');
estado.minimos = estado.minimos || {};
estado.alertados = estado.alertados || {};

const fmt = v => 'R$ ' + Number(v).toLocaleString('pt-BR', { maximumFractionDigits: 0 });
const fmtDur = m => `${Math.floor(m / 60)}h${String(m % 60).padStart(2, '0')}`;

const encontrados = [];
respostas.forEach((r, i) => {
  const b = buscas[i] ? buscas[i].json : null;
  if (!b) return;
  const j = r.json || {};
  if (j.error) return; // ex.: "Google Flights hasn't returned any results" -> sem voos ainda
  const voos = [...(j.best_flights || []), ...(j.other_flights || [])].filter(f => Number(f.price) > 0);
  if (!voos.length) return;
  voos.sort((a, c) => a.price - c.price);
  const top = voos[0];
  const trechos = top.flights || [];
  encontrados.push({
    ...b,
    preco: top.price,
    cias: [...new Set(trechos.map(t => t.airline))].join(' + '),
    paradas: Math.max(0, trechos.length - 1),
    duracao: top.total_duration ? fmtDur(top.total_duration) : '-',
    link: (j.search_metadata && j.search_metadata.google_flights_url) || 'https://www.google.com/travel/flights',
    nivel: j.price_insights ? j.price_insights.price_level : null,
    faixa: j.price_insights ? j.price_insights.typical_price_range : null,
  });
});

// Nenhum voo publicado ainda -> silêncio total.
if (!encontrados.length) return [];

const cfg = buscas[0].json.config;
const primeiraVez = !estado.disponivel;
estado.disponivel = true;

const alertas = [];
for (const e of encontrados) {
  const anterior = estado.minimos[e.chave];
  const motivos = [];
  if (primeiraVez && !anterior) motivos.push('voos publicados');
  if (anterior && e.preco <= anterior * (1 - cfg.QUEDA_MINIMA_PCT / 100)) motivos.push(`nova mínima (antes ${fmt(anterior)})`);
  if (e.preco <= cfg.PRECO_ALVO_TOTAL && estado.alertados[e.chave] !== e.preco) motivos.push('abaixo do preço-alvo');
  if (!anterior || e.preco < anterior) estado.minimos[e.chave] = e.preco;
  if (motivos.length) {
    estado.alertados[e.chave] = e.preco;
    alertas.push({ ...e, motivos });
  }
}

if (!alertas.length) return [];

alertas.sort((a, c) => a.preco - c.preco);
const nomeSaida = { FCO: 'Roma (FCO)', NAP: 'Nápoles (NAP)', BRI: 'Bari (BRI)' };
const linhas = alertas.map(a => `
  <tr>
    <td style="padding:8px;border-bottom:1px solid #E5E1D8;">${a.origem} → Roma<br><small>${a.ida}</small></td>
    <td style="padding:8px;border-bottom:1px solid #E5E1D8;">${nomeSaida[a.saida] || a.saida} → ${a.origem}<br><small>${a.volta}</small></td>
    <td style="padding:8px;border-bottom:1px solid #E5E1D8;"><strong>${fmt(a.preco)}</strong><br><small>${cfg.ADULTOS} adulto(s)${a.nivel ? ' · nível ' + a.nivel : ''}</small></td>
    <td style="padding:8px;border-bottom:1px solid #E5E1D8;">${a.cias}<br><small>${a.paradas} parada(s) · ${a.duracao} (ida)</small></td>
    <td style="padding:8px;border-bottom:1px solid #E5E1D8;"><small>${a.motivos.join('; ')}</small><br><a href="${a.link}">abrir no Google Voos</a></td>
  </tr>`).join('');

const melhor = alertas[0];
const html = `
<div style="font-family:Arial,Helvetica,sans-serif;max-width:720px;margin:0 auto;color:#182430;">
  <div style="background:#1F5C4A;padding:18px 22px;"><h2 style="color:#fff;margin:0;font-size:18px;">✈️ Radar Itália — Outubro 2027</h2></div>
  <div style="padding:20px;border:1px solid #E5E1D8;border-top:none;background:#fff;">
    <p style="margin-top:0;">${primeiraVez ? 'O Google Voos começou a mostrar voos para as suas datas.' : 'Há novidade de preço nas suas buscas.'}
    Melhor opção: <strong>${fmt(melhor.preco)}</strong> (${melhor.cias}).</p>
    <table style="width:100%;font-size:13px;border-collapse:collapse;">
      <tr style="text-align:left;color:#5C6A78;"><th style="padding:8px;">Ida</th><th style="padding:8px;">Volta</th><th style="padding:8px;">Preço total</th><th style="padding:8px;">Voo</th><th style="padding:8px;">Motivo</th></tr>
      ${linhas}
    </table>
    <p style="font-size:12px;color:#5C6A78;">Antes de comprar, compare no Skyscanner, Kayak, Momondo, Decolar e nos programas de milhas (Smiles, LATAM Pass, Azul Fidelidade, TAP Miles&amp;Go, Flying Blue). Preço-alvo configurado: ${fmt(cfg.PRECO_ALVO_TOTAL)}.</p>
  </div>
</div>`;

return [{ json: {
  from: cfg.EMAIL_REMETENTE,
  to: [cfg.EMAIL_DESTINO],
  subject: `✈️ Itália out/2027: ${fmt(melhor.preco)} — ${melhor.origem}→Roma ${melhor.ida}`,
  html,
  total_alertas: alertas.length,
} }];
